function murderScore(ctx,c){
var F=ctx.flags,m=F.motive;
var s=ctx.env.motive/100*0.35+F.pressure*0.12;
s+=c.tr.aggr*0.3+c.tr.cold*0.25+c.stress/100*0.4+c.tr.impulse*0.1;
if(m)s+=m.fit(c.tr)*0.25;
if(c.flags.grief!=null)s+=0.35;
if(c.flags.revenge!=null)s+=0.25;
if(c.goal.id==='out')s+=0.3;
if(c.goal.id==='nokill')s-=0.5;
if(c.goal.id==='protect')s-=0.2;
s-=c.tr.np*0.35;
if(c.tol!=null)s+=(c.tol-0.35)*0.45;
return s;
}
function isMM(ctx,c){return!!c&&ctx.flags.mm!=null&&c.i===ctx.flags.mm;}
function isTR(ctx,c){return!!c&&ctx.flags.tr!=null&&c.i===ctx.flags.tr;}
function mmOf(ctx){return ctx.flags.mm!=null?ctx.chars[ctx.flags.mm]:null;}
function trOf(ctx){return ctx.flags.tr!=null?ctx.chars[ctx.flags.tr]:null;}
function here(c){return!!c&&(HK.State&&HK.State.here?HK.State.here(c):c.alive&& !c.out);}
function mmHid(ctx){var m=mmOf(ctx);return m&&here(m)&& !ctx.flags.mmBust?m:null;}
function trHid(ctx){var t=trOf(ctx);return t&&here(t)&& !ctx.flags.trOut?t:null;}
