F.trOut=how;
ctx.act2({actors:by?[by,tr]:[tr],cat:how==='confess'?'solo':'conflict',mag:34,
fx:function(){ctx.present().forEach(function(o){if(o!==tr)ctx.mod(o,tr,how==='confess'?{trust: -18,ten:8}:{trust: -32,ten:16});});ctx.stress(tr,14);},
text:ctx.t(how==='confess'?ctx.pick(TR_CONFESS):ctx.pick(TR_EXPOSED[k]),tr,by),
why:(how==='confess'?tr.name+'の良心（NP・正直さ）が、黒幕への恐れに勝った':by.name+'の推理。細工と密告の痕跡（'+Math.round(F.trSus)+'）')+'。'+tr.name+'が黒幕に従っていた理由：'+F.trWhy});
