ctx.act2({actors:[tr].concat(b2?[b2]:[]),cat:'betray',mag:30,text:ctx.t(ctx.pick(b2?(stay?TR_END_STAY:TR_END[k2]):TR_END_SOLO),tr,b2),
why:tr.name+'は最後まで裏切り者だと知られなかった（演技力 '+ctx.stat(tr,'act')+'・'+TEMP_LABEL[k2]+'）。黒幕に従っていた理由：'+F.trWhy});
